def transform(grid):
    h, w = len(grid), len(grid[0])

    # Find full separator rows and columns.
    sep_rows = [r for r in range(h) if len(set(grid[r])) == 1 and grid[r][0] != 0]
    sep_cols = [c for c in range(w) if len({grid[r][c] for r in range(h)}) == 1 and grid[0][c] != 0]

    row_bounds = [-1] + sep_rows + [h]
    col_bounds = [-1] + sep_cols + [w]
    row_blocks = [(row_bounds[i] + 1, row_bounds[i + 1]) for i in range(len(row_bounds) - 1)]
    col_blocks = [(col_bounds[i] + 1, col_bounds[i + 1]) for i in range(len(col_bounds) - 1)]

    # The non-leftmost occupied panel contains the motif to replicate.
    motif = None
    for r0, r1 in row_blocks:
        for c0, c1 in col_blocks[1:]:
            cells = [[grid[r][c] != 0 for c in range(c0, c1)] for r in range(r0, r1)]
            if any(any(row) for row in cells):
                motif = cells
                break
        if motif is not None:
            break

    out = [[0] * w for _ in range(h)]
    for r in sep_rows:
        out[r] = grid[r][:]
    for c in sep_cols:
        for r in range(h):
            out[r][c] = grid[r][c]

    if motif is None:
        return out

    for r0, r1 in row_blocks:
        color = next((grid[r][c] for r in range(r0, r1)
                      for c in range(col_blocks[0][0], col_blocks[0][1])
                      if grid[r][c] != 0), 0)
        if not color:
            continue
        for c0, c1 in col_blocks:
            for dr in range(min(r1 - r0, len(motif))):
                for dc in range(min(c1 - c0, len(motif[dr]))):
                    if motif[dr][dc]:
                        out[r0 + dr][c0 + dc] = color
    return out
